#!/bin/sh
# E5c: reproducible Efinity run for engine_top on Ti60F225 (Titanium, timing model I3).
# Usage:  sh run.sh [flow]        flow = map | full   (default: full)
# Everything is written under ./outflow and ./work_syn; the RTL is read-only
# from ../../fpga_rtl_lab/target (generated by "veryl build"), never modified.
set -x
FLOW=${1:-full}
cd "$(dirname "$0")" || exit 2
rm -rf outflow work_syn
/usr/bin/efx_run engine_top \
    --family Titanium --device Ti60F225 --timing_model I3 \
    -f "$FLOW" \
    --flist synth.f \
    --output_dir outflow --work_dir work_syn
rc=$?
echo "efx_run exit=$rc flow=$FLOW"
exit $rc
